    reg [6:0] d;
    reg [5:0] sa;
    reg [5:0] sb;
    reg [5:0] sc;
    reg [5:0] sd;
    wire [6:0] max;
    wire [5:0] state;

    // Test tracking
    integer test_num;
    integer pass_count;
    integer fail_count;

    // Instantiate the DUT (Device Under Test)
    top_module dut (
        .a(a),
        .b(b),
        .c(c),
        .clk(clk),
        .d(d),
        .sa(sa),
        .sb(sb),
        .sc(sc),
        .sd(sd),
        .max(max),
        .state(state)
    );

    // Clock generation (10ns period)
    initial begin
        clk = 0;
        forever #5 clk = ~clk;
    end

        task reset_dut;

        begin
            a = 0; b = 0; c = 0; d = 0;
            sa = 0; sb = 0; sc = 0; sd = 0;
