description:
Design a 4-bit down counter that begins counting from 9 (representing decimal 10) and decrements on each clock pulse when enabled (EN=1). The counter resets to 0 when reset (rst_n=0). An output signal, oversuber, indicates when the counter has reached zero while enabled, signaling that it is no longer able to decrement further.
module top_module(clk,rst_n,EN,oversuber,Q
    );

code:
module top_module(clk,rst_n,EN,oversuber,Q
    );input clk,rst_n;
    input EN;                
    output oversuber;      
    output reg [3:0] Q;      


          always @(posedge clk or negedge rst_n) 
               begin
                   if (!rst_n)       
                     begin 
                      Q<=4'b0000;
                    end         
                   else if(EN==1)  
                     begin
                          if (Q==4'b0000)    
                               begin 
                                 Q<=4'b1001;    
                               end
                          else Q<=Q-4'b0001;      
                      end
               end
               assign oversuber=((EN==1)&&(Q==0))?1'b1:1'b0;

endmodule

