description:
Design a 4-bit binary adder that computes the sum of two 4-bit inputs, A and B. The output is a 5-bit result, C, which includes the 4-bit sum and an additional bit for the carry-out. The carry-out bit indicates if there was an overflow in the addition, allowing the user to detect if the sum exceeds the maximum representable value for 4 bits.
module top_module(
    input [3:0] A,
    input [3:0] B,
    output [4:0] C
);

code:
module top_module(
    input [3:0] A,
    input [3:0] B,
    output [4:0] C
);wire [3:0] sum;
wire carry_out;

assign sum = A + B;
assign carry_out = (sum[3] & A[3]) | (sum[3] & B[3]) | (A[3] & B[3]);

assign C[3:0] = sum;
assign C[4] = carry_out;

endmodule

