description:
Design a register transfer module that captures and stores execution stage outputs in a pipeline architecture of a CPU. This module operates on rising clock edges and reset conditions to load instruction, ALU output, write data, and program counter plus values from the execution stage. Upon reset, it initializes all stored values to zero, while otherwise retaining the latest values from its inputs (instrE, ALUOutE, WriteDataE, and pcplusE) for output to the subsequent memory stage (instrM, ALUOutM, WriteDataM, and pcplusM).
module top_module(clk,rst,instrE,ALUOutE,WriteDataE,pcplusE,
               instrM,ALUOutM,WriteDataM,pcplusM);

code:
module top_module(clk,rst,instrE,ALUOutE,WriteDataE,pcplusE,
               instrM,ALUOutM,WriteDataM,pcplusM);input         clk,rst;
   input [31:0]  instrE,ALUOutE,WriteDataE,pcplusE;
   output [31:0] instrM,ALUOutM,WriteDataM,pcplusM;

   reg [31:0]    _instr,_aluout,_writedata,_pcplus;

   always @(posedge clk or posedge rst) begin
      if (rst) begin
         _pcplus<=pcplusE;
         _instr<=32'h0;
         _aluout<=32'h0;
         _writedata<=32'h0;
      end
      else begin
         _instr<=instrE;
         _aluout<=ALUOutE;
         _writedata<=WriteDataE;
         _pcplus<=pcplusE;
      end
   end

   assign instrM=_instr;
   assign ALUOutM=_aluout;
   assign WriteDataM=_writedata;
   assign pcplusM=_pcplus;

endmodule

