description:
Design a clock generator module that takes an input clock signal and produces a toggled output clock signal operating at half the frequency of the input clock. Specifically, it operates as a frequency divider, generating a 50 MHz clock output when provided with a 100 MHz input clock. The internal counter tracks the number of cycles from the input clock, transitioning the output clock signal every 100 cycles to create the desired frequency. Additionally, the module includes a frequency checker mechanism that monitors the generated output clock to ensure proper operation and synchronization by alternating expected cycle counts between 50 MHz and 100 MHz.
module top_module(
    input clk_in,
    output reg clk_out
);

code:
module top_module(
    input clk_in,
    output reg clk_out
);// Clock period in ps
    localparam PER = 20;

    // Number of cycles for a 50 MHz clock
    localparam COUNT_50MHZ = 100;

    // Number of cycles for a 100 MHz clock
    localparam COUNT_100MHZ = 50;

    // Counter to keep track of the number of cycles
    reg [7:0] counter = 0;

    // Flip-flop to toggle the clock signal
    always @(posedge clk_in) begin
        counter <= counter + 1;
        if (counter == COUNT_100MHZ) begin
            counter <= 0;
            clk_out <= ~clk_out;
        end
    end

    // Frequency checker
    reg [31:0] count = 0;
    reg [31:0] expected_count = 0;
    reg locked = 0;

    always @(posedge clk_out) begin
        count <= count + 1;
        if (count == COUNT_50MHZ) begin
            count <= 0;
            if (expected_count == 0) begin
                expected_count <= COUNT_50MHZ;
            end else if (expected_count == COUNT_50MHZ) begin
                expected_count <= COUNT_100MHZ;
            end else if (expected_count == COUNT_100MHZ) begin
                expected_count <= COUNT_50MHZ;
            end

            if (count == expected_count) begin
                locked <= 1;
            end else begin
                locked <= 0;
            end
        end
    end

endmodule

